INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A1-01','A1','At the Hotel','Receptionist: Hello. What is your name?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A1-01-Q1','L-A1-01','listening','A1','What is the guest''s name?','["Maria", "Anna", "Emma", "Sara"]','Anna') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A1-01-Q2','L-A1-01','listening','A1','What room number?','["3", "5", "7", "9"]','5') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A1-02','A1','Shopping — Prices','Man: Excuse me, how much is this T-shirt?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A1-02-Q1','L-A1-02','listening','A1','How much is the T-shirt?','["$10", "$12", "$20", "$22"]','$12') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A1-03','A1','Family Intro','Boy: This is my family. This is my mother. She is a teacher. This is my father. He is a driver. I have one sister. She is five years old.',105,'British (slow)',25) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A1-03-Q1','L-A1-03','listening','A1','How many sisters does the boy have?','["0", "1", "2", "3"]','1') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A1-04','A1','Time and Day','Woman: What time is it?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A1-04-Q1','L-A1-04','listening','A1','What time is it?','["7:00", "8:00", "9:00", "10:00"]','8:00') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A1-05','A1','At the Cafe','Waiter: Hello, what would you like?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A1-05-Q1','L-A1-05','listening','A1','What does the customer order?','["Tea and cake", "Coffee and sandwich", "Juice and salad", "Water only"]','Coffee and sandwich') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A1-06','A1','Directions Simple','Man: Excuse me, where is the bus station?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A1-06-Q1','L-A1-06','listening','A1','Where is the bus station?','["Next to the supermarket", "Behind the park", "Opposite the school", "Near the river"]','Next to the supermarket') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A2-01','A2','Train Announcement','Announcement: The train to Manchester leaves from platform four at ten fifteen. Please have your tickets ready. The journey takes two hours. Food and drinks are available in carriage three.',120,'British',42) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A2-01-Q1','L-A2-01','listening','A2','Which platform?','["Platform 2", "Platform 3", "Platform 4", "Platform 5"]','Platform 4') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A2-01-Q2','L-A2-01','listening','A2','How long is the journey?','["1 hour", "2 hours", "3 hours", "2.5 hours"]','2 hours') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A2-02','A2','Weekend Plans','Sarah: What are you doing this weekend?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A2-02-Q1','L-A2-02','listening','A2','Where are Tom''s grandparents?','["Near the beach", "In the city", "Near the airport", "In the mountains"]','Near the beach') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A2-03','A2','Shopping Return','Customer: Hello, I bought this jacket yesterday but it is too small.
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A2-03-Q1','L-A2-03','listening','A2','Why does customer return jacket?','["Wrong color", "Too small", "Too expensive", "Damaged"]','Too small') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A2-04','A2','Doctor Appointment','Receptionist: Hello, City Clinic.
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A2-04-Q1','L-A2-04','listening','A2','When is appointment?','["Today 9AM", "Tomorrow 3PM", "Tomorrow 9AM", "Friday 3PM"]','Tomorrow 3PM') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A2-05','A2','Weather Forecast','Forecast: Tomorrow will be cloudy in the morning. In the afternoon, there will be light rain. The temperature will be fifteen degrees. On Friday, it will be sunny and warm, around twenty-two degrees.',118,'American',48) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A2-05-Q1','L-A2-05','listening','A2','What will weather be tomorrow afternoon?','["Sunny", "Light rain", "Heavy snow", "Windy"]','Light rain') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-A2-06','A2','Restaurant Order','Waiter: Are you ready to order?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-A2-06-Q1','L-A2-06','listening','A2','Total cost?','["£12", "£15", "£18", "£10"]','£15') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B1-01','B1','Travel Problems','Host: Today we talk about travel. Have you ever missed a flight?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B1-01-Q1','L-B1-01','listening','B1','Why did guest miss flight?','["Forgot passport", "Train delayed due to snow", "Traffic jam", "Overslept"]','Train delayed due to snow') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B1-01-Q2','L-B1-01','listening','B1','What did guest learn?','["Never travel in winter", "Always leave early in winter", "Take the bus", "Book earlier"]','Always leave early in winter') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B1-02','B1','University Life','Student: I moved to the university dormitory last month. At first it was difficult because I had never lived away from my family before. I had to cook and do laundry myself. But now I have made many friends on my floor and we study together in the evenings. My grades have improved since then.',142,'American',72) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B1-02-Q1','L-B1-02','listening','B1','What was difficult at first?','["Making friends", "Living away from family", "The coursework", "The city"]','Living away from family') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B1-03','B1','Job Interview Advice','Speaker: If you want to succeed in a job interview, you should research the company before you go. Think about why you want to work there and prepare examples of your skills. During the interview, listen carefully and don''t speak too quickly. And remember to ask a question at the end.',138,'Australian',65) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B1-03-Q1','L-B1-03','listening','B1','Not recommended?','["Research company", "Speak quickly", "Prepare skill examples", "Ask question at end"]','Speak quickly') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B1-04','B1','Healthy Lifestyle','Doctor: Many people think they need to go to the gym every day to stay healthy, but that''s not true. Walking for thirty minutes a day and eating more vegetables can make a big difference. Also, sleeping seven to eight hours is essential. If you follow these simple habits, you will feel much better within a few weeks.',140,'British',70) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B1-04-Q1','L-B1-04','listening','B1','According doctor, essential is?','["Gym every day", "Walking 30m + veg + 7-8h sleep", "Only diet", "Vitamins"]','Walking 30m + veg + 7-8h sleep') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B1-05','B1','Technology in Education','Teacher: Since we started using tablets in class, students are more engaged. They can watch videos and do interactive exercises. However, some parents are worried that children spend too much time on screens. We tell them that we limit tablet use to twenty minutes per lesson and encourage outdoor activities.',135,'American',75) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B1-05-Q1','L-B1-05','listening','B1','Parents worried about?','["Cost", "Too much screen time", "Battery", "Content"]','Too much screen time') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B1-06','B1','Cultural Festival','Guide: Welcome to the spring festival. This tradition started over two hundred years ago when farmers celebrated the end of winter. Today we still wear traditional clothes and dance in the streets. The festival lasts three days and thousands of tourists visit each year.',140,'British',60) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B1-06-Q1','L-B1-06','listening','B1','When did tradition start?','["50 years ago", "100 years ago", "Over 200 years ago", "500 years ago"]','Over 200 years ago') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B2-01','B2','Lecture: Urbanisation','Lecturer: Urbanisation is not simply people moving to cities. It involves profound economic and social transformations. In developing countries, the process has been remarkably rapid — what took a century in Europe has happened in three decades in parts of Asia. While this creates opportunities, particularly for young people seeking education, it also puts enormous pressure on housing, transport, and healthcare systems. Governments have struggled to keep pace, and as a result informal settlements have grown dramatically.',155,'British academic',95) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B2-01-Q1','L-B2-01','listening','B2','What point does lecturer make about developing countries?','["Urbanisation is slower than Europe", "Same speed as Europe", "Much faster — 3 decades vs a century", "Only young move"]','Much faster — 3 decades vs a century') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B2-01-Q2','L-B2-01','listening','B2','What consequence?','["More jobs only", "Pressure on housing/transport/health + informal settlements", "Less pollution", "Higher birth rate"]','Pressure on housing/transport/health + informal settlements') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B2-02','B2','News: Remote Work Debate','Reporter: The debate over remote work intensified this week after a major tech firm ordered all employees back to the office five days a week. Supporters argue that face-to-face collaboration sparks creativity and builds culture, whereas critics point to studies showing productivity remains stable or even improves at home. Moreover, many workers cite reduced commuting costs and better work-life balance as decisive factors in staying remote. The company''s decision has nevertheless been met with resignations.',150,'American',88) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B2-02-Q1','L-B2-02','listening','B2','Critics argue remote work productivity is?','["Much lower", "Stable or improved", "Unknown", "Slightly lower"]','Stable or improved') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B2-03','B2','Interview: Renewable Energy','Interviewer: Is renewable energy now economically viable?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B2-03-Q1','L-B2-03','listening','B2','Expert says solar cost?','["Increased 80%", "Fallen 80% in a decade, now cheapest", "Same", "Slightly fallen"]','Fallen 80% in a decade, now cheapest') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B2-04','B2','Discussion: Social Media & Mental Health','Psychologist: Research suggests a correlation, not necessarily causation, between heavy social media use and anxiety among teenagers. However, when usage exceeds three hours daily and replaces sleep or face-to-face interaction, the risk increases significantly. Parents should therefore focus less on banning and more on promoting balanced habits and open communication.',150,'Australian',85) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B2-04-Q1','L-B2-04','listening','B2','When does risk increase significantly?','[">1 hour daily", ">3 hours daily + replaces sleep/interaction", ">5 hours only if no friends", "Only with strangers"]','>3 hours daily + replaces sleep/interaction') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B2-05','B2','Lecture: Behavioral Economics','Professor: Traditional economics assumes we are rational actors, yet behavioral studies repeatedly show we are predictably irrational. For instance, people will drive twenty minutes to save five dollars on a fifteen-dollar item, but not on a thousand-dollar item, even though the saving is identical. This inconsistency reveals how context, not absolute value, drives decisions.',148,'American',92) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B2-05-Q1','L-B2-05','listening','B2','Example shows decisions driven by?','["Absolute value", "Context/framing", "Income", "Age"]','Context/framing') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-B2-06','B2','Podcast: Future of Work','Host: Automation will not simply eliminate jobs; it will transform them. Roles involving repetitive tasks are most vulnerable, whereas those requiring creativity, emotional intelligence, or complex problem-solving are likely to grow. Consequently, reskilling is no longer optional — it is imperative for both individuals and governments.',155,'British',90) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-B2-06-Q1','L-B2-06','listening','B2','Jobs likely to grow are?','["Repetitive manual", "Creativity/EI/complex problem-solving", "Data entry", "Assembly line"]','Creativity/EI/complex problem-solving') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C1-01','C1','Panel: AI Ethics','Moderator: Should we anthropomorphise AI?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C1-01-Q1','L-C1-01','listening','C1','Panellist 1 danger is?','["AI is slow", "Users infer empathy where only pattern matching", "AI is expensive", "Regulation is easy"]','Users infer empathy where only pattern matching') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C1-01-Q2','L-C1-01','listening','C1','Panellist 2 main concern?','["Speed", "Accountability vacuum / liability", "Cost", "Data size"]','Accountability vacuum / liability') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C1-02','C1','Lecture: Monetary Policy','Economist: Conventional wisdom held that low unemployment must drive inflation, yet the post-pandemic period confounded that model. Despite historically tight labour markets, inflation was initially driven by supply-chain disruptions, not wage pressure. The Federal Reserve, having misjudged transitory factors, was compelled to tighten aggressively, albeit at the risk of overtightening. Notwithstanding these challenges, the soft landing narrative has, to date, held.',168,'American academic',115) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C1-02-Q1','L-C1-02','listening','C1','What confounded model?','["Low unemployment must drive inflation — but inflation came from supply chains", "High unemployment drives inflation", "Inflation always transitory", "Wages drive supply chain"]','Low unemployment must drive inflation — but inflation came from supply chains') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C1-03','C1','Debate: Genetic Editing','Speaker: The ethical objection to germline editing often hinges on hubris — the notion that we should not ''play God''. Yet we already intervene extensively in nature. The more substantive concern, to my mind, is equity: were the technology to remain accessible only to the affluent, we risk entrenching a genetic divide that would make current inequalities look trivial. Nevertheless, a blanket prohibition would be equally problematic.',162,'British',108) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C1-03-Q1','L-C1-03','listening','C1','Speaker substantive concern?','["Playing God", "Equity — only affluent access → genetic divide", "Technical safety", "Religion"]','Equity — only affluent access → genetic divide') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C1-04','C1','Interview: Architecture & Sustainability','Architect: The fetishisation of glass towers is fundamentally at odds with climate goals. A truly sustainable building is not one that merely offsets its carbon, but one that embodies low-embodied-energy materials, passive ventilation, and adaptability over decades. Retrofitting existing stock, unglamorous as it may be, will have far greater impact than any number of flagship ''green'' skyscrapers.',165,'American',105) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C1-04-Q1','L-C1-04','listening','C1','Architect says greatest impact is?','["New green skyscrapers", "Retrofitting existing stock", "More glass towers", "Carbon offsets"]','Retrofitting existing stock') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C1-05','C1','Documentary: Language Death','Narrator: Every forty days, a language dies, taking with it an entire worldview. The process is rarely violent; rather, it is insidious. Parents, believing bilingualism burdens their children, switch to the dominant language. Within two generations, comprehension becomes passive, then vanishes. Documentation, while valuable, is palliative — it preserves a record, not a living tongue.',160,'British',112) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C1-05-Q1','L-C1-05','listening','C1','Process described as?','["Violent suppression", "Insidious — parents switch to dominant language", "Natural disaster", "Government ban"]','Insidious — parents switch to dominant language') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C1-06','C1','Lecture: Cognitive Biases','Psychologist: Confirmation bias is not merely seeking agreeable information; it is interpreting ambiguous evidence as supportive. Moreover, we exhibit bias blind spot — recognising bias in others while remaining oblivious to our own. Debiasing, therefore, requires not information but metacognition: the habit of interrogating one''s own reasoning.',165,'American',100) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C1-06-Q1','L-C1-06','listening','C1','Bias blind spot is?','["Seeking info", "Seeing bias in others but not self", "Forgetting", "Groupthink"]','Seeing bias in others but not self') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C2-01','C2','Oxford Union: Free Speech','Speaker: The paradox of deplatforming is that in attempting to deny a platform to noxious views, we inadvertently platform the very narrative of martyrdom those views crave. Free speech, properly understood, is not the absence of consequences, but the presence of contestation. To sanitise the public square of all discomfort is to infantilise it — and infantilised publics, as history attests, are not resilient but brittle.',175,'Mixed (British/American, fast, idiomatic)',125) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C2-01-Q1','L-C2-01','listening','C2','Paradox of deplatforming?','["It works perfectly", "Denies platform but platforms martyrdom narrative", "Too expensive", "Illegal"]','Denies platform but platforms martyrdom narrative') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C2-01-Q2','L-C2-01','listening','C2','Speaker view: sanitised square leads to?','["Resilience", "Brittleness/infantilised public", "Economic growth", "Consensus"]','Brittleness/infantilised public') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C2-02','C2','Satirical Review: Tech Utopianism','Critic: Silicon Valley''s latest promise — that an app will ''disrupt'' loneliness — is, with exquisite irony, being pitched by the very ecosystem that engineered it. The solution to a problem caused by substituting connection with connectivity is, apparently, more connectivity, albeit with a subscription. One is reminded of the old quip that the cover-up is worse than the crime, except here the cover-up is the business model.',178,'British (rapid, humour, irony)',120) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C2-02-Q1','L-C2-02','listening','C2','Critic irony?','["App solves loneliness but ecosystem caused it", "App is free", "Loneliness is natural", "Tech reduces connectivity"]','App solves loneliness but ecosystem caused it') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C2-03','C2','Supreme Court Oral Argument','Justice: Counsel, your reading would render the savings clause a nullity — a textbook surplusage problem. How do you square that with the canon against superfluity?
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C2-03-Q1','L-C2-03','listening','C2','Justice concern?','["Savings clause becomes nullity / surplusage", "Too much precedent", "Jurisdiction", "Standing"]','Savings clause becomes nullity / surplusage') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C2-04','C2','Literary Lecture: Unreliable Narrator','Professor: The brilliance of Ishiguro''s narrator is not that he lies, but that he deceives himself with such consummate politeness that we collude. The hedged recollections — ''perhaps it was'', ''one might have thought'' — are not lapses of memory but acts of self-preservation. To parse his account is to become complicit in the very repression he performs.',175,'British',118) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C2-04-Q1','L-C2-04','listening','C2','Narrator deception is?','["Outright lying", "Self-deception with politeness; reader colludes", "Forgetting", "Multiple narrators"]','Self-deception with politeness; reader colludes') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C2-05','C2','Geopolitics Briefing','Analyst: The conventional framing of this conflict as a binary — autocracy versus democracy — collapses under scrutiny. The belligerents are not monoliths; patronage networks cut across ideological lines, and the war economy has created vested interests in perpetuation. Any settlement that ignores these granular realities, however normatively appealing, will be stillborn.',176,'Mixed',122) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C2-05-Q1','L-C2-05','listening','C2','Analyst rejects?','["Economic factors", "Binary autocracy vs democracy framing", "Historical context", "Negotiation"]','Binary autocracy vs democracy framing') ON CONFLICT DO NOTHING;
INSERT INTO training_listening (id,cefr,title,audio_script,wpm,accent,duration_s) VALUES ('L-C2-06','C2','Philosophy: Moral Luck','Philosopher: Nagel''s problem of moral luck is vertiginous: two drivers, equally reckless, swerve identically, yet one, by luck, kills a child who darts into the road, the other does not. Our reactive attitudes — blame, guilt — track outcome, not just agency. If we accept that luck permeates agency itself — constitutive luck — then the very ground of moral assessment trembles.',174,'American',128) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('L-C2-06-Q1','L-C2-06','listening','C2','Moral luck example?','["Two equally reckless drivers, one kills by luck → blame tracks outcome", "One driver careful", "Both punished equally", "Luck irrelevant"]','Two equally reckless drivers, one kills by luck → blame tracks outcome') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-A1-01','A1','My Day','Hello! My name is Lina. I am twelve years old. I live in Jakarta with my mother, father and brother. I go to school at seven o''clock. My school is near my house. I ride a bicycle to school. I like my school. My favourite subject is English. My teacher is Mrs Sari. She is very kind. After school I play football with my friends. In the evening I do my homework and watch TV. I go to bed at nine o''clock.',138) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A1-01-Q1','R-A1-01','reading','A1','How does Lina go to school?','["By bus", "By bicycle", "By car", "On foot"]','By bicycle') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A1-01-Q2','R-A1-01','reading','A1','What is Lina''s favourite subject?','["Math", "Science", "English", "Art"]','English') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A1-01-Q3','R-A1-01','reading','A1','When does she go to bed?','["8:00", "9:00", "10:00", "7:00"]','9:00') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-A1-02','A1','The Supermarket','The supermarket is open from eight in the morning to nine at night. It is on Green Street. You can buy food, drinks and clothes there. Apples are two dollars. Milk is one dollar. Bread is three dollars. On Saturday there are many people. On Sunday the supermarket is closed. I go there with my mother on Friday.',132) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A1-02-Q1','R-A1-02','reading','A1','When is supermarket closed?','["Saturday", "Sunday", "Friday", "Monday"]','Sunday') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A1-02-Q2','R-A1-02','reading','A1','How much is bread?','["$1", "$2", "$3", "$4"]','$3') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-A1-03','A1','My Cat','I have a cat. Its name is Mimi. It is white and grey. It is two years old. It likes to sleep on my bed. It likes fish and milk. Every morning I give it food. It plays with a ball in the garden. I love my cat very much.',128) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A1-03-Q1','R-A1-03','reading','A1','What does Mimi like to eat?','["Fish and milk", "Bread and cheese", "Chicken and rice", "Cake"]','Fish and milk') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-A1-04','A1','My Friend','This is my friend Budi. He is thirteen. He lives in Surabaya. He has short black hair and brown eyes. He likes playing badminton. He plays every Saturday with his brother. He wants to be a doctor. He studies hard every day. He is a good friend.',145) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A1-04-Q1','R-A1-04','reading','A1','What sport does Budi like?','["Football", "Badminton", "Basketball", "Tennis"]','Badminton') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A1-04-Q2','R-A1-04','reading','A1','What does Budi want to be?','["Teacher", "Doctor", "Driver", "Pilot"]','Doctor') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-A2-01','A2','A Trip to Bali','Last holiday my family went to Bali. We travelled by plane from Jakarta. The flight took two hours. We stayed in a small hotel near the beach. Every morning we swam in the sea and in the afternoon we visited temples. One day we went to Ubud and saw traditional dancing. The people were very friendly and the food was delicious. We bought some souvenirs and took many photos. We came back home on Sunday. I want to go there again next year.',196) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A2-01-Q1','R-A2-01','reading','A2','How did they travel to Bali?','["By train", "By plane", "By bus", "By car"]','By plane') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A2-01-Q2','R-A2-01','reading','A2','What did they see in Ubud?','["Modern art", "Traditional dancing", "A concert", "A football match"]','Traditional dancing') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A2-01-Q3','R-A2-01','reading','A2','When did they return?','["Saturday", "Sunday", "Monday", "Friday"]','Sunday') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-A2-02','A2','Learning English','I started learning English two years ago. At first it was difficult because I didn''t know many words. Now I study for one hour every day. I watch English videos on YouTube and read short stories. My teacher says my speaking is getting better, but my writing is still weak. I want to improve because I need English for my future job. Next year I will take an English course in the evenings after work.',205) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A2-02-Q1','R-A2-02','reading','A2','When did the writer start learning English?','["One year ago", "Two years ago", "Three years ago", "Six months ago"]','Two years ago') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A2-02-Q2','R-A2-02','reading','A2','What is still weak?','["Speaking", "Listening", "Writing", "Reading"]','Writing') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-A2-03','A2','My Hometown','I live in a small town near Yogyakarta. It is not very big but it is quiet and clean. There are two schools, a market and a hospital. The most famous place is the old palace. Many tourists visit it every weekend. I like my town because the people are kind and the air is fresh. However, there are not many jobs, so many young people move to big cities like Jakarta or Surabaya.',188) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A2-03-Q1','R-A2-03','reading','A2','Why do young people leave?','["Pollution", "Not many jobs", "Expensive", "No school"]','Not many jobs') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-A2-04','A2','A New Phone','Yesterday I bought a new phone. It cost three million rupiah. It has a big screen and a good camera. I can take photos and play games. I also use it to study English. There is an app where I can talk to people from other countries. I have already talked to someone from Canada and Australia. It is very interesting.',192) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-A2-04-Q1','R-A2-04','reading','A2','How much did the phone cost?','["1 million", "3 million", "5 million", "2 million"]','3 million') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-B1-01','B1','Why Do People Travel?','People have travelled for thousands of years, but travelling for pleasure is a relatively recent idea. In the past, people travelled only if they needed to — for trade, war or religion. Today, many people travel because they want to experience new cultures and meet new people. Travelling can be educational. When you visit another country, you learn about its history, food and traditions. You also learn about yourself because you have to deal with unexpected situations. However, mass tourism can cause problems. Popular destinations become crowded and expensive, and local cultures can be damaged. Therefore, many experts suggest that travellers should choose less famous places and respect local customs. If tourists behave responsibly, tourism can help local economies without harming the environment.',312) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B1-01-Q1','R-B1-01','reading','B1','In the past, people travelled mainly for?','["Pleasure", "Trade/war/religion", "Education", "Health"]','Trade/war/religion') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B1-01-Q2','R-B1-01','reading','B1','What do experts suggest?','["Visit only famous places", "Choose less famous places and respect customs", "Never travel", "Travel alone"]','Choose less famous places and respect customs') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B1-01-Q3','R-B1-01','reading','B1','Mass tourism can?','["Help without any problem", "Cause crowding, higher prices, cultural damage", "Only help economy", "Only damage roads"]','Cause crowding, higher prices, cultural damage') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-B1-02','B1','Working From Home','Since the pandemic, millions of people have started working from home. For many, this change has been positive. They save time because they don''t need to commute, and they can spend more time with their families. Companies also save money on office costs. However, working from home is not perfect. Some people feel lonely because they don''t see their colleagues. Others find it difficult to separate work and home life — they work longer hours and feel stressed. Psychologists recommend creating a separate workspace and taking regular breaks. If you work from home, you should also make time to meet friends and exercise. People who follow this advice usually feel happier and more productive.',298) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B1-02-Q1','R-B1-02','reading','B1','Positive of WFH according passage?','["Save commute time + family time, companies save costs", "Faster promotion", "More holidays", "Less work"]','Save commute time + family time, companies save costs') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B1-02-Q2','R-B1-02','reading','B1','Psychologists recommend?','["Work in bed", "Separate workspace + breaks", "Work longer", "No breaks"]','Separate workspace + breaks') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-B1-03','B1','Fast Fashion','Fast fashion describes clothes that are cheap and follow the latest trends. Companies produce millions of items every month and sell them at low prices. As a result, people buy more clothes than they need and throw them away quickly. This causes serious environmental problems. Making clothes uses a lot of water and chemicals, and most discarded clothes end up in landfills. Although some brands have started using recycled materials, the majority still produce in the same way. Consumers can help by buying fewer clothes, choosing quality over quantity, and donating what they no longer wear. If everyone made small changes, the impact would be significant.',305) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B1-03-Q1','R-B1-03','reading','B1','Fast fashion is?','["Expensive and durable", "Cheap and trend-driven, high volume"]','Cheap and trend-driven, high volume') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B1-03-Q2','R-B1-03','reading','B1','What can consumers do?','["Buy more", "Buy fewer, choose quality, donate"]','Buy fewer, choose quality, donate') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-B1-04','B1','Learning a Second Language','Many studies have shown that learning a second language is good for the brain. Bilingual people can often focus better and switch between tasks more quickly. They may also delay the onset of dementia. However, learning a language is not easy. Most people need at least two years of regular practice to reach an intermediate level. The key is consistency — studying a little every day is more effective than studying for many hours once a week. Although apps and online courses are helpful, research shows that interaction with real people is the best way to improve speaking skills. Therefore, learners should try to find conversation partners if possible.',322) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B1-04-Q1','R-B1-04','reading','B1','Bilingual benefit?','["Better focus/task switching, may delay dementia", "Larger height", "Faster running", "No benefit"]','Better focus/task switching, may delay dementia') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B1-04-Q2','R-B1-04','reading','B1','What is most effective?','["Many hours once a week", "A little every day + real interaction"]','A little every day + real interaction') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-B2-01','B2','The Attention Economy','In the past, information was scarce and attention was abundant. Today the opposite is true: we are inundated with information, and attention has become the scarcest resource. Technology companies have built entire business models around capturing and monetising attention. Social media platforms are designed to maximise the time users spend scrolling, using techniques borrowed from behavioural psychology, such as variable rewards — the same mechanism that makes slot machines addictive. As a result, many people find it increasingly difficult to concentrate for extended periods. Studies have shown that heavy smartphone users struggle not only with focus but also with memory consolidation, as constant task-switching prevents deep processing. Although some argue that the solution is simply to exercise willpower, research suggests that environmental design is more powerful than individual discipline. Therefore, experts recommend restructuring one''s digital environment: disabling non-essential notifications, setting app limits, and designating phone-free periods. Moreover, cultivating practices such as sustained reading or mindfulness meditation can help rebuild attentional capacity. It is claimed that even a week of reduced screen time can lead to measurable improvements in wellbeing. Consequently, reclaiming attention is not merely a personal productivity issue but a broader societal challenge that requires both individual and collective action.',468) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B2-01-Q1','R-B2-01','reading','B2','Business model built on?','["Selling devices", "Capturing/monetising attention", "Advertising only", "Subscriptions"]','Capturing/monetising attention') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B2-01-Q2','R-B2-01','reading','B2','Mechanism compared to?','["Lottery", "Slot machines / variable rewards", "Video games only", "TV"]','Slot machines / variable rewards') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B2-01-Q3','R-B2-01','reading','B2','Experts argue solution is?','["Willpower only", "Restructuring digital environment + practices like reading/meditation"]','Restructuring digital environment + practices like reading/meditation') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-B2-02','B2','Urban Green Spaces','As cities expand, the importance of urban green spaces has become increasingly apparent. Parks, community gardens, and street trees provide not only aesthetic benefits but also crucial environmental services. They reduce the urban heat island effect, absorb air pollutants, and manage stormwater runoff. Moreover, access to green spaces has been linked to significant mental health benefits, including reduced stress and anxiety. Having grown rapidly without adequate planning, many cities in developing countries now face a deficit of such spaces. Recently, planners have begun to integrate green infrastructure into urban design, rather than treating it as an afterthought. For example, Singapore''s Park Connector Network links major parks with tree-lined corridors, encouraging physical activity while preserving biodiversity. While it was once believed that economic growth and environmental preservation were mutually exclusive, evidence suggests they can be complementary. Cities that invest in green spaces often see increased property values and tourism revenue. Therefore, the question for policymakers is no longer whether to invest, but how much and where.',445) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B2-02-Q1','R-B2-02','reading','B2','Green spaces environmental services?','["Only aesthetic", "Reduce heat island, absorb pollutants, manage runoff"]','Reduce heat island, absorb pollutants, manage runoff') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B2-02-Q2','R-B2-02','reading','B2','Singapore example?','["No green spaces", "Park Connector Network links parks with corridors"]','Park Connector Network links parks with corridors') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-B2-03','B2','The Future of Food','Feeding a global population of nearly ten billion by 2050 will require fundamental changes to how we produce food. Agriculture already accounts for approximately seventy percent of freshwater use and is a major driver of deforestation. Although it has been argued that simply increasing yields will be sufficient, recent research indicates that dietary shifts are equally important. Reducing meat consumption, particularly beef, could free up vast areas of land and significantly cut greenhouse gas emissions. Having recognised this, some governments have introduced incentives for plant-based diets, while food companies are investing in alternative proteins, such as lab-grown meat and insect-based products. However, cultural attitudes remain a significant barrier, as meat is deeply embedded in many culinary traditions. Therefore, transition strategies must be culturally sensitive and economically viable for farmers. Ultimately, the future of food will depend not on a single solution but on a combination of technological innovation, policy reform, and behavioural change.',432) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B2-03-Q1','R-B2-03','reading','B2','Major driver of freshwater use/deforestation?','["Transport", "Agriculture ~70% freshwater"]','Agriculture ~70% freshwater') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B2-03-Q2','R-B2-03','reading','B2','Needed according research?','["Only yield increase", "Yield + dietary shifts (reduce beef)"]','Yield + dietary shifts (reduce beef)') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-B2-04','B2','Misinformation','The spread of misinformation has been dramatically accelerated by social media, where false stories often travel faster than verified ones. Research has shown that novelty and emotional content — particularly outrage — make misinformation more shareable. While it is tempting to attribute the problem solely to malicious actors, studies indicate that ordinary users inadvertently share false information when they fail to verify sources. Moreover, algorithms that prioritise engagement amplify sensational content, creating echo chambers in which users are rarely exposed to contradictory views. Having identified the mechanisms, researchers are now exploring interventions. Fact-checking, while useful, has limited reach, as corrections rarely achieve the same virality as the original false claim. More promising are pre-emptive approaches, such as media literacy education and prompts that encourage users to pause and reflect before sharing. Consequently, addressing misinformation requires a multi-faceted strategy that combines platform accountability, education, and individual responsibility. As one scholar noted, the antidote to misinformation is not censorship but critical thinking.',458) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B2-04-Q1','R-B2-04','reading','B2','Why does misinformation spread faster?','["Longer", "Novelty + emotional/outrage"]','Novelty + emotional/outrage') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-B2-04-Q2','R-B2-04','reading','B2','More promising than fact-checking?','["Censorship", "Pre-emptive: media literacy + pause prompts"]','Pre-emptive: media literacy + pause prompts') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-C1-01','C1','The Paradox of Choice','Conventional economic theory posits that more choice is inherently beneficial, as it maximises the likelihood that individuals will find an option precisely suited to their preferences. However, psychologist Barry Schwartz has argued that an overabundance of choice can be detrimental to wellbeing, leading to what he terms the paradox of choice. When confronted with myriad options — whether among thirty varieties of jam or hundreds of career paths — individuals often experience decision paralysis, followed by dissatisfaction regardless of outcome. This dissatisfaction stems not from the chosen option''s objective quality but from the counterfactual reasoning it engenders: the nagging sense that a foregone alternative might have been superior. What is particularly insidious is that this process is self-reinforcing. Were consumers to adopt a satisficing strategy — accepting a ''good enough'' option rather than relentlessly maximising — they would report higher satisfaction, yet the cultural imperative to optimise proves difficult to resist. Notwithstanding the intuitive appeal of maximising, evidence suggests that those who satisfice experience less regret and greater psychological resilience. Moreover, the proliferation of choice has structural implications. Platforms that aggregate infinite options, from streaming services to dating apps, implicitly promise an ideal match, thereby raising expectations to unattainable levels. The inevitable gap between expectation and reality fuels a pervasive sense of inadequacy. Consequently, the challenge is not to eliminate choice but to architect environments that facilitate meaningful decisions without overwhelming cognitive resources. Minimalist movements and curated selections can be understood as rational responses to an otherwise cognitively exhausting marketplace.',612) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C1-01-Q1','R-C1-01','reading','C1','Paradox of choice is?','["More choice always better", "Overabundance → paralysis + dissatisfaction via counterfactual reasoning"]','Overabundance → paralysis + dissatisfaction via counterfactual reasoning') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C1-01-Q2','R-C1-01','reading','C1','Satisficing vs maximising?','["Maximising happier", "Satisficing → less regret, more resilience"]','Satisficing → less regret, more resilience') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C1-01-Q3','R-C1-01','reading','C1','Platforms with infinite options do?','["Lower expectations", "Raise expectations to unattainable levels → inadequacy"]','Raise expectations to unattainable levels → inadequacy') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-C1-02','C1','Decoupling Economic Growth from Emissions','For decades, the relationship between economic growth and carbon emissions was assumed to be tightly coupled: to grow was to emit. Recently, however, a number of advanced economies have demonstrated that decoupling is possible. Not only have countries such as Denmark and the United Kingdom reduced absolute emissions while maintaining growth, but they have done so while improving living standards. The mechanisms are multifaceted. Having invested heavily in renewable infrastructure, these economies have substantially decarbonised electricity generation. Concurrently, structural shifts from manufacturing to services have reduced energy intensity. Nevertheless, sceptics caution against complacency. What concerns them is that territorial accounting obscures the outsourcing of emissions — goods consumed domestically but manufactured abroad still generate carbon, albeit attributed to another country''s ledger. Were consumption-based accounting to be adopted, the apparent decoupling would appear considerably less impressive. Furthermore, the historical responsibility of advanced economies cannot be discounted; they have already consumed the majority of the remaining carbon budget. Thus, while decoupling offers a valuable proof of concept, its scalability to rapidly industrialising nations remains uncertain. Ultimately, the discourse must move beyond aggregate growth figures to consider the composition and distribution of growth itself.',588) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C1-02-Q1','R-C1-02','reading','C1','Decoupling example countries?','["US and China", "Denmark and UK — reduced emissions while growing"]','Denmark and UK — reduced emissions while growing') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C1-02-Q2','R-C1-02','reading','C1','Sceptics concern?','["Price", "Territorial vs consumption-based accounting — outsourcing hides emissions"]','Territorial vs consumption-based accounting — outsourcing hides emissions') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-C1-03','C1','The Biology of Bilingualism','The bilingual brain has long intrigued neuroscientists, not merely for its linguistic capacity but for its implications for cognitive reserve. It was once feared that early bilingualism might burden the developing mind, causing confusion or delay. Contemporary research decisively repudiates this view. Having been exposed to two languages from infancy, bilingual children demonstrate enhanced executive control — the ability to inhibit one language while activating the other, a mental exercise that generalises to non-linguistic domains. What is particularly striking is the structural consequence: neuroimaging reveals increased grey matter density in the anterior cingulate cortex among lifelong bilinguals. Were this advantage to translate into clinical outcomes, the implications would be profound. Indeed, epidemiological studies suggest that bilingualism can delay the symptomatic onset of Alzheimer''s by approximately five years, even after controlling for education and socioeconomic status. Nevertheless, the effect is probabilistic, not deterministic; bilingualism is no guarantee against neurodegeneration, but rather a contributing factor to cognitive resilience. Moreover, the benefit appears dose-dependent, contingent on sustained, active use of both languages, rather than passive knowledge. Consequently, the narrative should not be that bilingualism is a panacea, but that it exemplifies how sustained cognitive engagement shapes brain architecture. The broader lesson concerns neuroplasticity itself: the brain remains malleable, provided it is challenged.',605) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C1-03-Q1','R-C1-03','reading','C1','Early fear vs contemporary view?','["Fear burden → repudiated; enhances executive control"]','Fear burden → repudiated; enhances executive control') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C1-03-Q2','R-C1-03','reading','C1','Alzheimer delay?','["~5 years, even controlling education/SES, but probabilistic"]','~5 years, even controlling education/SES, but probabilistic') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-C1-04','C1','Algorithmic Governance','The deployment of algorithmic systems in governance — from credit scoring to predictive policing — promises efficiency and ostensible objectivity, yet it embeds normative choices that often remain opaque. An algorithm is not a neutral arbiter but a crystallisation of its designers'' assumptions, data, and objectives. Having optimised for historical patterns, such systems inevitably reproduce the biases therein. What concerns critics is not merely that bias exists, but that it becomes laundered through a veneer of mathematical legitimacy, thereby becoming harder to contest. Were a human official to make an equivalent judgment, recourse would be relatively straightforward; when an algorithm errs, accountability dissipates across a chain of vendors, datasets, and proprietary code. Notwithstanding these challenges, outright rejection would be imprudent. The alternative — unexamined human discretion — is itself rife with inconsistency and prejudice. Rather, what is needed is a framework of algorithmic accountability that mandates transparency, auditability, and meaningful human oversight. This entails not only technical measures, such as explainability requirements, but also institutional ones, including independent review boards. Ultimately, the question is not whether to use algorithms, but how to govern them in a manner that preserves due process while harnessing their potential.',595) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C1-04-Q1','R-C1-04','reading','C1','Algorithm bias becomes?','["Easily fixed", "Laundered via mathematical legitimacy → harder to contest"]','Laundered via mathematical legitimacy → harder to contest') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C1-04-Q2','R-C1-04','reading','C1','Accountability when algorithm errs?','["Clear", "Dissipates across vendors/datasets/code"]','Dissipates across vendors/datasets/code') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-C2-01','C2','The Epistemology of Conspiracy Theories','Conspiracy theories are often dismissed as mere irrationality, a dismissal that itself betrays a misunderstanding of their epistemic structure. Far from being bereft of reasoning, they exhibit a hyper-rationality — an assiduous connecting of dots that, precisely because it is unconstrained by parsimony, generates an internally coherent but empirically vacuous edifice. The conspiratorial worldview is self-sealing: absence of evidence is recast as evidence of the cover-up''s efficacy, and contradictory data is subsumed as deliberate disinformation. This hermetic quality renders falsification, the cornerstone of scientific reasoning, impotent. What is particularly vertiginous is the conspiratorial reversal of epistemic virtue: whereas science valorises the provisional and the tentative, conspiracism valorises certitude and comprehensiveness — the promise that nothing is accidental, nothing is as it seems, and everything is connected. That promise exerts a powerful existential allure, furnishing order in a contingent world and absolving the believer of the burden of ambiguity. To counter this, debunking, while superficially appealing, is often self-defeating, as it replicates the adversarial framing that sustains the worldview. More promising are interventions that operate at the level of epistemic norms — cultivating intellectual humility, probabilistic reasoning, and the capacity to tolerate explanatory incompleteness. Notwithstanding such efforts, the sociological conditions that incubate conspiracism — atomisation, institutional distrust, and the democratisation of content creation without commensurate gatekeeping — suggest that it is less an aberration than a symptom. To treat it as a cognitive defect, therefore, is to misdiagnose a fundamentally political and social phenomenon. The remedy, if there is one, lies not in correcting discrete falsehoods but in rebuilding the epistemic commons itself — the shared infrastructure of trust, verification, and accountability that makes collective sense-making possible.',712) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C2-01-Q1','R-C2-01','reading','C2','Conspiracy theories structure is?','["Irrational", "Hyper-rational, self-sealing, absence of evidence = cover-up efficacy"]','Hyper-rational, self-sealing, absence of evidence = cover-up efficacy') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C2-01-Q2','R-C2-01','reading','C2','Why debunking often fails?','["Too slow", "Replicates adversarial framing that sustains worldview"]','Replicates adversarial framing that sustains worldview') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C2-01-Q3','R-C2-01','reading','C2','Deeper remedy according author?','["More facts", "Rebuilding epistemic commons — trust/verification/accountability"]','Rebuilding epistemic commons — trust/verification/accountability') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-C2-02','C2','Monetary Sovereignty and the Euro','The eurozone''s architecture embodies a fundamental asymmetry: monetary union without fiscal union, a central bank without a sovereign, credit without a lender of last resort for its constituent states. Under the gold standard, adjustment to economic shocks was brutally simple — deflation and unemployment — but politically intolerable. The euro, by design, replicates this rigidity in a modern guise. Member states cannot devalue their currency, nor can they monetise debt; they are, in the phrase of one economist, users rather than issuers of currency. The crisis of 2010 laid bare this design flaw. Having borrowed in what was effectively a foreign currency, periphery states found themselves subject to the sudden stop dynamics more commonly associated with emerging markets, despite being advanced economies with ostensibly institutional credibility. The policy response — austerity — was not merely economically contractionary but conceptually incoherent within a monetary union, as simultaneous fiscal retrenchment across interdependent economies amplified rather than mitigated the downturn. What was lacking, and remains lacking, is a mechanism for cyclical stabilisation at the union level: a common treasury, Eurobonds, or a genuine transfer union. German ordoliberalism, with its categorical aversion to moral hazard, has consistently blocked such mechanisms, viewing them as exculpation rather than insurance. Yet the alternative — permanent divergence between core and periphery, punctuated by recurrent crises — is itself a profound moral hazard, as it entrenches a hierarchy of states within a purported community of equals. The tragedy of the euro, in this reading, is not that integration went too far, but that it stopped halfway.',698) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C2-02-Q1','R-C2-02','reading','C2','Eurozone asymmetry?','["Fiscal without monetary", "Monetary union without fiscal union; states users not issuers of currency"]','Monetary union without fiscal union; states users not issuers of currency') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C2-02-Q2','R-C2-02','reading','C2','2010 periphery crisis resembled?','["US states", "Emerging markets sudden stop dynamics despite advanced status"]','Emerging markets sudden stop dynamics despite advanced status') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C2-02-Q3','R-C2-02','reading','C2','Blocked mechanism and reason?','["Common treasury / Eurobonds blocked by ordoliberal moral hazard concerns"]','Common treasury / Eurobonds blocked by ordoliberal moral hazard concerns') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-C2-03','C2','The Aesthetics of Impermanence','The Japanese concept of wabi-sabi — often mistranslated as rustic simplicity — more accurately denotes an aesthetic attuned to impermanence, imperfection, and incompleteness. It is the beauty of the weathered stone, the irregular glaze, the garden that is never finished because it is never static. Western aesthetics, by contrast, has historically valorised permanence and perfection: the marble statue that defies time, the symmetrical façade that asserts order over contingency. That these are divergent responses to the same existential fact — that all things pass — is itself illuminating. Wabi-sabi does not merely tolerate transience but finds in it the very condition of beauty; the crack in the tea bowl, repaired with lacquer and gold in the kintsugi technique, is not hidden but illuminated, because the history of breakage is integral to the object''s meaning. To dismiss this as mere sentimentality is to overlook its philosophical sophistication. Underpinning wabi-sabi is a Zen-inflected ontology in which being is not substance but process, not noun but verb. The cherry blossom is beautiful not despite its ephemerality but because of it; its brief flowering is a memento mori that sharpens rather than attenuates appreciation. In an age of planned obsolescence and digital simulacra, where the new is fetishised and the old discarded, wabi-sabi offers a quiet but radical reorientation: to cherish what is, precisely because it will not always be. That such a reorientation is itself impermanent — that wabi-sabi, too, will fade — is not a refutation but its ultimate confirmation.',685) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C2-03-Q1','R-C2-03','reading','C2','Wabi-sabi accurately denotes?','["Rustic simplicity", "Aesthetic attuned to impermanence/imperfection/incompleteness"]','Aesthetic attuned to impermanence/imperfection/incompleteness') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C2-03-Q2','R-C2-03','reading','C2','Kintsugi crack is?','["Hidden", "Illuminated with gold — history integral to meaning"]','Illuminated with gold — history integral to meaning') ON CONFLICT DO NOTHING;
INSERT INTO training_passages (id,cefr,title,passage,word_count) VALUES ('R-C2-04','C2','The Crowd Within','Gustave Le Bon''s proclamation that the crowd renders the individual barbaric has proven remarkably durable, despite being empirically threadbare. Contemporary crowd psychology, notably the social identity perspective pioneered by Reicher and colleagues, inverts Le Bon''s formulation: people in crowds do not lose identity but shift from personal to social identity, acting not as atomised egos but as members of a salient group. The implications are profound. What appears from the outside as mindless uniformity is, from within, norm-governed behaviour — albeit norms that are locally constructed and situationally emergent. Were a football crowd to chant in unison, it is not because its members have been hypnotised but because chanting is what it means, in that moment, to be a proper supporter. That this account restores agency to crowd members is its most significant contribution, yet it also complicates questions of responsibility. If crowd action is meaningful rather than mechanical, then moral evaluation cannot be suspended, even if causal attribution becomes more intricate. Notwithstanding this nuance, institutional responses remain stubbornly Le Bonian: the deployment of overwhelming force to coerce compliance, a strategy that, by treating a crowd as an undifferentiated mass, often precipitates precisely the confrontation it purports to prevent. The paradox is stark: the myth of the irrational crowd, by informing policing tactics, helps produce the very irrationality it presupposes — a self-fulfilling prophecy written in riot gear.',705) ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C2-04-Q1','R-C2-04','reading','C2','Social identity vs Le Bon crow theory?','["Lose identity → barbaric", "Shift personal→social identity, norm-governed not mindless"]','Shift personal→social identity, norm-governed not mindless') ON CONFLICT DO NOTHING;
INSERT INTO training_questions (id,passage_id,skill,cefr,question,options,answer) VALUES ('R-C2-04-Q2','R-C2-04','reading','C2','Policing based on Le Bon myth does?','["Prevents violence", "Often precipitates confrontation it purports to prevent — self-fulfilling prophecy"]','Often precipitates confrontation it purports to prevent — self-fulfilling prophecy') ON CONFLICT DO NOTHING;
INSERT INTO training_grammar (id,cefr,type,question,options,answer,explanation) VALUES ('G-A1-01','A1','grammar','___ name is Anna.','["My", "I", "Me", "Mine"]','My','Possessive adjective before noun') ON CONFLICT DO NOTHING;
