INSERT INTO training_grammar (id,cefr,type,question,options,answer,explanation) VALUES ('G-C2-10','C2','vocab','The findings ___ conventional wisdom on its head.','["turned", "put", "kept", "brought"]','turned','Turn on its head = invert') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A1-01','A1','Write a postcard to a friend (30-40 words).','Hello Ana! I am in Bali. It is very nice. The beach is big and beautiful. I swim every day. I love Bali. See you soon! Love, Sari.',26,'{"content": 3, "communicative": 3, "organisation": 2, "language": 2}','Simple present, and/but only, spelling ok, no complex.') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A1-02','A1','Fill form: introduce yourself','My name is Budi. I am 15 years old. I live in Jakarta. I am a student. My hobby is football.',18,'{"content": 2, "communicative": 2, "organisation": 2, "language": 2}','Very short, basic pattern My name is... I am...') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A1-03','A1','Describe your family','My family have 4 people. Mother, father, sister and me. My mother is cook. My father go to work every day. My sister is 10. I love my family.',27,'{"content": 3, "communicative": 2, "organisation": 2, "language": 1}','Agreement errors (have/has, is/are), but understandable A1') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A1-04','A1','Describe your house','My house is small. It have 2 bedrooms. It is blue. I like my house. It near school.',17,'{"content": 2, "communicative": 2, "organisation": 1, "language": 1}','Missing be: It near school → error typical A1') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A1-05','A1','Write about your pet','I have a cat. It name is Mimi. It is white. It is cute. I give it fish. I love my cat.',20,'{"content": 3, "communicative": 3, "organisation": 2, "language": 2}','Its vs It error but clear') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A1-06','A1','Message to friend','Hi Rina! How are you? I am fine. Let''s play tomorrow at 3 o''clock in the park. Bye!',17,'{"content": 3, "communicative": 3, "organisation": 2, "language": 2}','Formulaic greeting + invitation') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A2-01','A2','Email to friend about holiday (60 words)','Hi Tom, Last holiday I went to Yogyakarta with my family. We went by train. We visited the palace and tried gudeg. It was very delicious. We stayed for three days and took many photos. I want to go again next year. How was your holiday? Write soon! Best, Dina',45,'{"content": 4, "communicative": 3, "organisation": 3, "language": 3}','Past simple, very short linked text, personal letter conventions') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A2-02','A2','Describe your hobby','My hobby is playing badminton. I play every Saturday with my friend at the school hall. I started two years ago. At first it was difficult but now I can play well. My father taught me. I want to join a competition next year.',42,'{"content": 4, "communicative": 3, "organisation": 3, "language": 3}','Past simple + present, because/but, simple connectors') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A2-03','A2','Write about your school','My school is not very big but it is very clean. There are 20 classrooms and a small library. My favourite place is the canteen because the food is cheap and delicious. The teachers are kind. I have many friends there. I like going to school every day.',43,'{"content": 4, "communicative": 3, "organisation": 3, "language": 3}','There are, because, but — A2 range') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A2-04','A2','Message about birthday','Dear Sari, Thank you for your invitation to your birthday party. I would love to come on Saturday. What time does it start? Do you need me to bring anything? I will bring a small gift. See you soon! Love, Ani',36,'{"content": 4, "communicative": 4, "organisation": 3, "language": 3}','Invitation reply, would love, question forms') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A2-05','A2','Describe daily routine','I get up at six o''clock every day. Then I take a shower and have breakfast with my family. I go to school by bus. School starts at seven and finishes at two. After school I do my homework and play games. I go to bed at nine.',44,'{"content": 4, "communicative": 3, "organisation": 3, "language": 3}','Present simple routine, then/after, time phrases') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-A2-06','A2','Write about shopping','Yesterday I went to the mall with my mother. We bought a new dress for my sister. It was blue and very pretty. It cost 200,000 rupiah. My mother also bought shoes. We were very tired but happy after shopping.',38,'{"content": 4, "communicative": 3, "organisation": 3, "language": 3}','Past simple narrative, and/but, adjectives') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B1-01','B1','Email to friend about moving (80 words)','Hi Sarah, I have great news! We moved to a new house last month. It is bigger than our old house and has a small garden. At first I felt sad because I missed my old friends, but now I have made new friends at my new school. My new school is not far and I ride my bicycle there every day. If you have time, please visit me next holiday. I would love to show you my new room! Write soon. Love, Maya',78,'{"content": 4, "communicative": 4, "organisation": 4, "language": 3}','Present perfect (have made), although? No — but B1: comparatives, conditionals 1, past + present mix') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B1-02','B1','Opinion: Is online learning good?','In my opinion online learning has both advantages and disadvantages. The main advantage is that students can study at home and save time. They can also watch lessons again if they don''t understand. However the disadvantage is that students may feel lonely and they need good internet. I think online learning is useful but schools should use both online and face-to-face methods. This is the best way for students to learn well.',72,'{"content": 4, "communicative": 4, "organisation": 4, "language": 3}','However, because, if, both…and, modals can/should') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B1-03','B1','Describe a memorable trip','Last year I went to Lombok with my cousins. We travelled by plane and stayed in a small hotel near the beach. We swam every morning and visited traditional villages in the afternoon. I have never seen such beautiful beaches before. The people were very friendly and the food was delicious. I learned many things about Lombok culture on this trip. I will never forget it.',68,'{"content": 4, "communicative": 4, "organisation": 4, "language": 4}','Past + present perfect (have never seen), such...') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B1-04','B1','Letter complaining','Dear Sir/Madam, I am writing to complain about the hotel I stayed in last weekend. I booked a double room but I was given a small single room. Moreover the bathroom was not clean and the air conditioner did not work. I asked the staff to change my room but they said the hotel was full. I would like a refund. I look forward to your reply. Yours faithfully, Andi',71,'{"content": 5, "communicative": 4, "organisation": 4, "language": 4}','Formal letter conventions, past, passive (was given, was not clean)') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B1-05','B1','Future plans','In the future I want to be an English teacher. I have studied English for two years and I enjoy it very much. If I pass the university entrance exam, I will study English Education. I know it will be difficult but I will try hard. My parents support my plan and I hope I can achieve my dream.',52,'{"content": 4, "communicative": 4, "organisation": 3, "language": 3}','Future with will, if conditional, have studied') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B1-06','B1','Describe festival','In my town we have a harvest festival every August. It starts with a parade and traditional music. People wear colourful clothes and dance in the streets. In the evening there are fireworks. Last year more than 5,000 people came to the festival. It is a wonderful event that brings everyone together. I always look forward to it.',58,'{"content": 4, "communicative": 4, "organisation": 4, "language": 4}','Present for routine + past for specific, that clause') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B2-01','B2','Essay: Should university education be free? (200w)','It is often argued that university education should be free for all students. While this idea is attractive, I believe it is not practical for most countries. On the one hand, free education would give equal opportunities to poor students and help reduce inequality. Moreover society as a whole would benefit because more people would be qualified for skilled jobs. On the other hand, governments would need to raise taxes significantly, which could be unpopular. Although some countries such as Germany have made higher education free, they have strong tax systems and well-funded public sectors. In countries where public funding is limited, making universities free might reduce quality because there would be less money for facilities and research. Having considered these arguments, I believe a better approach is to provide scholarships and low-interest loans for students who need them, while still charging fees for those who can afford to pay. This would ensure both accessibility and quality.',148,'{"content": 5, "communicative": 4, "organisation": 5, "language": 4}','Although/while/moreover/having considered, passive (is argued), conditionals, cohesive devices B2+') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B2-02','B2','Report: Social media pros/cons (180w)','The aim of this report is to examine the effects of social media on teenagers. Recent surveys have shown that teenagers spend an average of three hours daily on platforms such as Instagram and TikTok. The main advantage is that social media allows young people to stay connected with friends and to express themselves creatively. However it also has serious drawbacks. Having been exposed to idealised images, many teenagers develop low self-esteem and anxiety. It is claimed that heavy use can disrupt sleep and reduce concentration. Although it would be unrealistic to ban social media, schools and parents should promote balanced use. Therefore the recommendation is that teenagers be encouraged to limit screen time and to prioritise face-to-face interaction.',118,'{"content": 5, "communicative": 5, "organisation": 5, "language": 4}','Report register, passive reporting (is claimed, have shown), although/therefore, gerunds') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B2-03','B2','Essay: Remote work is future','Although remote work was once considered unusual, it has become common since the pandemic. Many employees argue that working from home improves productivity because there are fewer distractions. Employers also benefit because they can save on office costs. However, critics point out that remote work may weaken team cohesion and make collaboration more difficult. It could also disadvantage young employees who need mentoring. On balance, while remote work offers significant advantages, it is unlikely to replace office work entirely. A hybrid model, which combines both approaches, seems to be the most sustainable solution for most companies.',94,'{"content": 4, "communicative": 4, "organisation": 5, "language": 4}','Although, while, however, on balance, gerund, modal could') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B2-04','B2','Formal letter application','Dear Hiring Manager, I am writing to apply for the position of Marketing Intern advertised on your website. I am currently in my third year of Business Administration at Gadjah Mada University, where I have maintained a GPA of 3.7. Having completed an internship at a digital agency last summer, I have gained experience in social media management and data analysis. Moreover I am fluent in English and proficient in Adobe Photoshop. I have attached my CV and would be grateful for the opportunity to discuss my application. I look forward to hearing from you. Yours sincerely, Aditya',98,'{"content": 5, "communicative": 5, "organisation": 5, "language": 4}','Formal letter, having completed..., present perfect, proficient') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B2-05','B2','Article: Importance reading','In an era dominated by short videos and instant messages, the habit of sustained reading is in decline. This is a matter of concern because reading does far more than convey information; it trains attention, fosters empathy, and builds vocabulary. Studies have shown that people who read regularly have better concentration and are more adept at understanding different perspectives. While it is true that digital media offers convenience, it rarely requires the deep processing that books demand. Therefore schools should actively promote reading programmes, not as an old-fashioned chore but as an essential skill for critical thinking.',88,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','While, therefore, not as…but as, have shown, dominant') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-B2-06','B2','Opinion: Tourism good?','Tourism is often seen as beneficial because it creates jobs and generates income. However mass tourism can have detrimental effects. Popular destinations become overcrowded, which damages both the environment and the visitor experience. Having visited Bali during peak season, I witnessed firsthand how traffic and waste detract from the island''s beauty. Although governments have introduced visitor caps in some areas, enforcement remains inconsistent. Consequently a more sustainable approach is needed — one that prioritises quality over quantity and ensures local communities benefit directly.',78,'{"content": 5, "communicative": 4, "organisation": 5, "language": 5}','However, having visited..., although, consequently, prioritises') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C1-01','C1','Essay: AI in education — opportunity or threat? (250w)','What concerns me most about the rapid integration of artificial intelligence into education is not its technical capability, which is considerable, but the pedagogical vacuum in which it is often deployed. Were schools to adopt AI as a mere labour-saving device, the result would be the automation of mediocrity: faster marking, but not deeper learning. The true potential lies elsewhere — in using AI to diagnose misconceptions and to tailor feedback at a granularity no human teacher could feasibly achieve for thirty students simultaneously. Nevertheless this potential is contingent on teachers remaining the architects of learning, not its bystanders. It is imperative that curricula emphasise evaluative judgment, lest students cede not only tasks but also thinking to machines. Were this to happen, the very skills that AI cannot replicate — critical synthesis, ethical reasoning, creative leap — would atrophy precisely when they are most needed. Notwithstanding these risks, a blanket prohibition would be equally misguided, as it would deprive students of literacy in the defining technology of their generation. Ultimately the question is not whether to integrate AI, but how to do so in a manner that augments rather than supplants human agency. That such a balance is achievable is evident from early pilots where AI handles routine feedback while teachers focus on Socratic dialogue.',198,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Cleft (What concerns), inversion (Were schools...), hedging, nominalisation, cohesive Nevertheless/Notwithstanding') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C1-02','C1','Report: Decoupling growth from emissions','The aim of this report is to assess whether economic growth can be decoupled from carbon emissions. Recent evidence from several advanced economies suggests that absolute decoupling is feasible. Having invested heavily in renewables, Denmark has cut emissions by forty percent while sustaining growth. What is striking is that this was achieved not through deindustrialisation alone but through genuine efficiency gains. However, consumption-based accounting tells a less sanguine story. Were imports to be included, the apparent decoupling would diminish considerably, as many carbon-intensive goods are now manufactured abroad. Moreover the historical carbon debt of advanced economies remains unaddressed. Therefore while decoupling offers a valuable precedent, its transferability to rapidly industrialising nations is far from assured. It is recommended that policy frameworks adopt consumption-based metrics and that support for green technology transfer be substantially increased.',132,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Having invested, What is striking cleft, Were imports... inversion, passive reporting') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C1-03','C1','Proposal: Bilingual education','Bilingual education was once feared to burden the developing mind, yet contemporary research decisively repudiates this assumption. Were children to be exposed to two languages from infancy, they would develop enhanced executive control — the capacity to inhibit one language while activating the other, an exercise that generalises to non-linguistic domains. Not only would this confer cognitive advantages, but it would also delay, probabilistically, the onset of neurodegenerative symptoms. Nevertheless implementation requires sustained, active use of both languages; passive exposure alone is insufficient. It is therefore proposed that schools adopt a dual-immersion model, wherein subjects are taught in alternating languages, rather than confining the second language to a discrete subject. Such a model is admittedly resource-intensive, but the evidence suggests the investment pays dividends in both academic and health outcomes.',128,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Inversion, cleft, hedging probabilistically, nominalisation') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C1-04','C1','Article: Paradox of choice','That an abundance of choice should breed dissatisfaction is, at first glance, paradoxical. Conventional wisdom holds that more options maximise the probability of an optimal match. Yet the proliferation of choice, from streaming catalogues to dating apps, has engendered decision paralysis and the nagging sense that a forgone alternative might have been superior. Were consumers to satisfice — to accept a good-enough option — they would report higher wellbeing, yet the injunction to optimise remains culturally hegemonic. What this reveals is that choice is not merely an instrumental good but a symbolic one; to choose maximally is to perform competence. The remedy, therefore, is not to eliminate choice but to curate it — to impose, paradoxically, a constraint that liberates.',108,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Nominalisation, That-clause fronted, inversion Were..., cleft What this reveals') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C1-05','C1','Essay: Should we regulate social media like tobacco?','The analogy between social media and tobacco is more apt than it initially appears. Both products were marketed as benign, both were later shown to exploit known vulnerabilities — nicotine in one case, variable rewards in the other — and both disproportionately affect the young. What distinguishes them is the regulatory lag: whereas tobacco is now heavily circumscribed, social media remains largely self-governed, despite mounting evidence of harm. Were regulators to apply the same precautionary principle, restrictions on design features that maximise engagement — infinite scroll, autoplay — would be a logical first step. Notwithstanding the importance of free expression, product design is not speech. Consequently, framing regulation as censorship misconstrues the issue; what is at stake is not what can be said, but how attention is engineered. That such a framing has been resisted owes less to constitutional principle than to lobbying power.',132,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Both...both, were regulators, notwithstanding, what is at stake cleft') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C1-06','C1','Formal letter: Complaint policy','Dear Director, I am writing to express concern about the recently introduced attendance policy, which mandates dismissal after three absences. While I appreciate the need for consistency, the policy is, in my view, unduly rigid. Not only does it fail to distinguish between avoidable and unavoidable absences, but it also disproportionately penalises students with caregiving responsibilities. Were the policy to be amended to allow for documented extenuating circumstances, it would retain its disciplinary intent while demonstrating institutional empathy. It is imperative that policies be both firm and humane. I would welcome the opportunity to discuss this matter further. Yours faithfully, Nabila',96,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Not only inversion, were...to be amended, imperative subjunctive') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C2-01','C2','Essay: Is impartiality possible? (250w)','That journalism can be impartial is a proposition that, upon scrutiny, dissolves into a category mistake — as if perspective were a blemish to be expunged rather than the very condition of understanding. Every account, however austere, necessarily selects, frames, and foregrounds; impartiality, if it means the absence of standpoint, is not an ideal but an impossibility. What is at stake, therefore, is not the elimination of perspective but its disciplined disclosure. To conflate objectivity with neutrality is to misread the epistemic virtue: objectivity entails not that one has no commitments, but that one is willing to hold them defeasibly, to test them against countervailing evidence. The reporter''s obligation is not to stand nowhere — a view from nowhere is, as Nagel observed, itself a view from somewhere — but to render her standpoint auditable, so that the reader may discount for bias. Were this norm to be widely internalised, the discourse would shift from the sterile theatre of balance — where every fact is offset by a counter-fact, however spurious — to a more robust accountability, where claims are adjudicated by their warrant, not their symmetry. That such a shift remains elusive owes less to philosophical confusion than to economic incentive: engagement rewards the performance of neutrality while penalising the labour of transparency. In this sense, the crisis of impartiality is less epistemological than structural — a symptom of a business model that profits from the ambiguity it purports to lament.',208,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Fronted That-clause, cleft What is at stake, inversion Were..., nominalisation, hedging, sophisticated discourse') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C2-02','C2','Essay: Wabi-sabi and modernity','Wabi-sabi, often platitudinously rendered as ''rustic simplicity'', more precisely denotes an aesthetic attuned to impermanence, imperfection, and incompleteness — the weathered stone, the irregular glaze, the bowl repaired with gold where the crack is illuminated rather than concealed. Its philosophical import lies not in nostalgia but in ontology: being is construed as process, not substance. That Western aesthetics has historically valorised permanence — the marble that defies time — renders wabi-sabi a quiet but radical reorientation. To cherish what is precisely because it will not endure is to invert the logic of consumption, which fetishises the new and discards the old. Notwithstanding its apparent quietism, wabi-sabi is thus profoundly subversive in an age of planned obsolescence. That it, too, will pass is not a refutation but its ultimate confirmation.',122,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Parenthetical em dashes, fronted That-clause, attenuated hedging, nominalisation') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C2-03','C2','Essay: Moral luck','Nagel''s problem of moral luck is vertiginous precisely because it renders our reactive attitudes incoherent. Two drivers, equally reckless, swerve identically; one, by luck, kills a child who darts into the road, the other does not. We blame the former more, yet by what warrant, if their agency was identical and only luck differentiated outcome? Were we to accept that constitutive luck — the luck of who we are — permeates agency itself, then the very ground of moral assessment trembles. Not that morality is thereby vacuous, but that its pretence to immunity from luck stands refuted. Little did Nagel anticipate that his puzzle would find empirical corroboration in neuroscience, where readiness potentials precede conscious decision by milliseconds, suggesting that the will, if it exists, is less sovereign than we imagined.',118,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Inversion Little did..., subjunctive Were we to accept, nominalisation vertiginous') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C2-04','C2','Essay: Decoupling under scrutiny','That decoupling — the severing of growth from emissions — should be celebrated as proof of concept is understandable, but to extrapolate from territorial accounting is to indulge in a statistical artefact. Had consumption-based metrics been adopted, the apparent miracle would have been revealed as, in large part, an exercise in carbon arbitrage: emissions not reduced but relocated. Moreover, the historical carbon debt — the cumulative appropriation of atmospheric commons by early industrialisers — remains unacknowledged in frameworks that reset the clock at 1990. Were equity to be taken seriously, the remaining budget would be allocated not per capita in the present but in recognition of past appropriation. That such a reckoning is politically infeasible does not make it any less analytically correct. Notwithstanding the elegance of green-growth narratives, the question that persists is whether prosperity can be reconceived without the compulsion to grow at all.',134,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Inversion Had...been, fronted That-clause, hedging, nominalisation') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C2-05','C2','Essay: Free speech paradox','The paradox of deplatforming is that in attempting to deny a platform to noxious views, it inadvertently platforms the very narrative of martyrdom those views crave. Free speech, properly understood, is not the absence of consequence but the presence of contestation. To sanitise the public square of all discomfort — to render it, in effect, anodyne — is to infantilise it. That infantilised publics are brittle, not resilient, is a lesson history has taught at great cost. Were we to defend speech on the grounds of resilience rather than virtue, we would need to tolerate not merely the agreeable but the discomforting, and to equip citizens not with censorship but with the capacity for rebuttal. Not to do so is to cede the ground of legitimation to those who claim that truth fears examination.',118,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Nominalisation, inversion Were we..., fronted That-clause, hedging') ON CONFLICT DO NOTHING;
INSERT INTO training_writing_samples (id,cefr,prompt,text,word_count,rubric,note) VALUES ('W-C2-06','C2','Essay: Euro tragedy','The tragedy of the euro is not that integration went too far but that it stopped halfway — monetary union without fiscal union, a central bank without a sovereign, credit without a lender of last resort. Member states, having borrowed in what was effectively a foreign currency, found themselves subject to sudden-stop dynamics more commonly associated with emerging markets. That austerity — simultaneous fiscal retrenchment across interdependent economies — should have amplified the downturn was entirely predictable within a monetary union, yet it was prescribed as if the eurozone were a collection of discrete households. Little did the architects anticipate that ordoliberal aversion to moral hazard would itself become a profound moral hazard, entrenching a hierarchy of states within a purported community of equals.',108,'{"content": 5, "communicative": 5, "organisation": 5, "language": 5}','Ellipsis dash, having borrowed..., fronted That-clause, inversion Little did...') ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A1-01','A1','Personal Q&A (30s)','What is your name? Where do you live? How old are you?','My name is Rina. I live in Bandung. I am 14 years old.',30) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A1-02','A1','Personal Q&A','What is your hobby?','My hobby is football. I like football very much.',30) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A1-03','A1','Describe picture','Describe this picture: a family in a park (one sentence each)','There are four people. They are in the park. They are happy.',40) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A1-04','A1','Daily routine','What do you do every morning?','I get up at six. I eat breakfast. I go to school.',30) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A1-05','A1','Simple request','Ask for the time','Excuse me, what time is it?',20) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A1-06','A1','Numbers/prices','How much is the book? (Answer: $5)','It is five dollars.',20) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A2-01','A2','Personal + past','What did you do last weekend? (40s)','Last weekend I went to the mall with my mother. We bought clothes and ate noodles. It was fun.',40) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A2-02','A2','Describe place','Describe your town (40s)','My town is small but clean. There is a market and a school. I like it because people are friendly.',45) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A2-03','A2','Plans','What will you do tomorrow?','Tomorrow I will visit my grandmother. I will go by bus in the morning.',35) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A2-04','A2','Shopping dialogue','Role-play: return a shirt that is too small','Hello, I bought this shirt yesterday but it is too small. Can I change it for a bigger size?',40) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A2-05','A2','Compare','Compare two phones you know','This phone is cheaper than that one. But that one has a better camera.',35) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-A2-06','A2','Directions','How do you get to school?','I go straight and turn left. My school is next to the mosque.',30) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B1-01','B1','Narrative (60s)','Talk about a memorable trip you took. Where did you go, who with, what happened?','Last year I went to Bali with my family. We stayed near the beach and visited temples. The most memorable part was the traditional dance in Ubud. I have never seen anything like it before. If I have the chance, I will go again.',60) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B1-02','B1','Opinion','Do you prefer studying alone or with friends? Why?','I prefer studying with friends because we can help each other. When I don''t understand something, my friend can explain. However, sometimes it is noisy, so I also study alone before exams.',60) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B1-03','B1','Describe experience','Describe a time you learned something difficult','Two years ago I learned to ride a motorbike. At first I was very nervous and I failed. But I practised every weekend and now I can ride well. It taught me not to give up.',60) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B1-04','B1','Future plans','What are your plans for next year?','Next year I will finish high school. If I pass the exam, I will study at university. I want to study English because I want to be a teacher.',55) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B1-05','B1','Give advice','Give advice to a friend who wants to learn English','You should practise every day, even for 30 minutes. Watching English videos can help. Also, try to speak with friends, don''t be afraid of mistakes.',60) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B1-06','B1','Compare past/present','How has your town changed in the last 10 years?','My town has changed a lot. There are more buildings and a new mall. Life is more convenient, but there is also more traffic.',60) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B2-01','B2','Argument (90s)','Some people say social media does more harm than good. Do you agree?','While social media has drawbacks, such as addiction and misinformation, its benefits should not be dismissed. It connects people across distances and gives voice to marginalised groups. However, having been designed to maximise engagement, it can be harmful when used excessively. Therefore, the key is balanced use rather than prohibition.',90) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B2-02','B2','Describe + evaluate','Describe a city you would like to live in and explain why','I would like to live in Singapore because it combines efficiency with green spaces. Having visited last year, I was impressed by the Park Connector Network which links parks with cycling paths. Although living costs are high, the quality of life compensates.',90) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B2-03','B2','Hypothetical','If you could change one thing about your education, what would it be?','If I could change one thing, it would be to have had more practical projects. Although theoretical knowledge is important, we rarely apply it. Having completed an internship recently, I realised how valuable hands-on experience is.',85) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B2-04','B2','Discuss trend','Why do many young people want to be influencers?','It is often claimed that influencing is easy money, but that overlooks the intense competition. Moreover, social media platforms amplify the visibility of success while obscuring the majority who fail. Consequently, aspirations are shaped by survivorship bias.',90) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B2-05','B2','Problem-solution','How can cities reduce traffic congestion?','While expanding roads has been the traditional response, evidence suggests it induces demand. More effective are investments in public transport and congestion pricing. Singapore, for instance, has shown that combining both can work.',85) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-B2-06','B2','Narrate with reflection','Talk about a challenge you overcame','When I first started university, I struggled to manage time between coursework and a part-time job. I learned to prioritise and to say no. Having developed a weekly planning system, my grades actually improved despite working.',90) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C1-01','C1','Sophisticated argument (90s)','Should AI be used to grade student essays? Discuss advantages and risks','Were AI to be used as a sole arbiter, I would be deeply concerned — not least because of the accountability vacuum that arises when an algorithm errs. That said, as an augmentative tool that diagnoses patterns across large cohorts, its potential is considerable. What is crucial is that teachers remain the architects of judgment, lest evaluative expertise atrophy.',90) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C1-02','C1','Abstract topic','Does more choice make us happier?','Paradoxically, an overabundance of choice tends to breed dissatisfaction. Were consumers to satisfice rather than maximise, they would report higher wellbeing, yet the cultural imperative to optimise proves difficult to resist. What this reveals is that choice is symbolic as well as instrumental.',90) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C1-03','C1','Evaluate policy','Should governments regulate social media design features like infinite scroll?','What distinguishes product design from speech is central here. Were regulators to frame restrictions as product safety rather than censorship, a coherent rationale emerges. Notwithstanding free-expression concerns, infinite scroll is not expression but engineered attention capture.',95) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C1-04','C1','Hypothetical ethical','If you could edit genes to prevent disease, should you? Where to draw line?','The substantive concern is not hubris but equity. Were germline editing to remain accessible only to the affluent, we would entrench a genetic divide that would dwarf current inequalities. Nevertheless, a blanket prohibition would deprive those who could be cured.',95) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C1-05','C1','Describe nuanced','Describe a book that changed your thinking','Not only did Ishiguro''s novel unsettle my assumptions about memory, but it did so through self-deception rendered with such politeness that I found myself colluding. Were I to single out one lesson, it would be that unreliable narration can be ethically revealing.',90) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C1-06','C1','Speculate future','How will climate change affect where people live in 50 years?','Had adaptation been prioritised earlier, displacement might have been mitigated. As it stands, low-lying regions face existential pressure. Notwithstanding technological optimism, the political question is who bears the cost of relocation.',95) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C2-01','C2','Subtle argument + irony (90s)','Is impartiality in journalism possible or even desirable?','That impartiality should be equated with neutrality betrays a category mistake; every account necessarily selects and frames. Were we to defend objectivity, we should mean not the absence of standpoint but its disciplined disclosure — rendering it auditable so readers may discount for bias. That journalism currently performs neutrality while being incentivised to amplify is the deeper structural issue.',100) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C2-02','C2','Philosophical','Does luck undermine moral responsibility? (moral luck)','Nagel''s vertiginous puzzle is that two equally reckless drivers who swerve identically are blamed differently by luck of outcome. Were constitutive luck — who we are — to be taken seriously, the very ground of moral assessment trembles. Little did we expect neuroscience to corroborate this with readiness potentials.',100) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C2-03','C2','Aesthetic abstract','Can impermanence be beautiful? Discuss wabi-sabi versus Western permanence','That impermanence should be the condition of beauty rather than its negation is precisely what wabi-sabi illuminates — the crack repaired with gold is beautiful because its history is integral, not despite it. To dismiss this as sentimentality is to overlook its ontology of process.',95) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C2-04','C2','Geopolitical nuance','Is the world becoming more multipolar or more fragmented?','The binary of multipolarity versus fragmentation collapses under scrutiny; patronage networks cut across ideological lines, and the war economy creates vested interests in perpetuation. Any settlement that ignores these granular realities, however normatively appealing, will be stillborn.',100) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C2-05','C2','Crowd psychology critique','Are crowds irrational?','Le Bon''s proclamation that crowds render individuals barbaric has proven empirically threadbare. Contemporary social identity theory inverts it: participants shift from personal to social identity, acting as group members. The irony is that treating crowds as undifferentiated masses often precipitates the very confrontation policing purports to prevent.',95) ON CONFLICT DO NOTHING;
INSERT INTO training_speaking (id,cefr,task,prompt,expected,duration_s) VALUES ('S-C2-06','C2','Tech critique satirical','Will an app solve loneliness?','That an app should ''disrupt'' loneliness is, with exquisite irony, pitched by the ecosystem that engineered it. Substituting connectivity for connection and then selling more connectivity as remedy is, to borrow the quip, a cover-up that is the business model. One is reminded that the cover-up is worse than the crime, except here they are identical.',100) ON CONFLICT DO NOTHING;